 * @hidden N
*/
scwin.init_datefmt_cal_grntEndDate = function () { $c.date.checkCalendarFormat("cal_grntEndDate", "yyyyMMdd"); };

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_isuStartDate();
        scwin.init_datefmt_cal_isuEndDate();
        scwin.init_datefmt_cal_listStartDate();
        scwin.init_datefmt_cal_listEndDate();
        scwin.init_datefmt_cal_grntStartDate();
        scwin.init_datefmt_cal_grntEndDate();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf35000.onpageload' });
    }
};


