/**
 * @method
 * @name scwin.Chk_Date
 * @author Inswave
 * @date 2026. 09. 29
 * @param Name Date_Str
 * @returns
 * @hidden N
*/
scwin.Chk_Date = async function (Name, Date_Str) {
    /* sdd-asis-lifecycle:begin Chk_Date — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let sdate = Name.getValue(); if (sdate == null) { sdate = ''; }
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(4, 2);
    pday = sdate.substr(6, 2);
    src = pyear + '-' + pmonth + '-' + pday;
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate !== "" && (syear !== soyear || smonth !== somonth || sday !== soday)) {
        await $c.win.alert("입력한 " + Date_Str + "이 올바르지 않습니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate !== "" && sdate.length != 8) {
        await $c.win.alert("입력한 " + Date_Str + "이 8자리가 아닙니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate === "") {
        Name.setValue('');
    } else {
        Name.setValue(sdate);
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
